type Role = 'directeur' | 'professeur' | 'secretaire' | 'comptable';
type View = 'dashboard' | 'students' | 'student-detail' | 'staff' | 'classes' | 'timetable' | 'qr' | 'bulletins' | 'finance' | 'attendance' | 'grades' | 'messages' | 'settings';
type Icon = ComponentType<{ size?: number; strokeWidth?: number; className?: string }>;
type Tone = 'violet' | 'green' | 'amber' | 'pink' | 'blue' | 'red';
type AttendanceStatus = 'present' | 'late' | 'absent' | 'excused';

type Student = {
  id: string; code: string; name: string; className: string; sexe: 'F' | 'G'; birthDate: string;
  status: 'Actif' | 'À compléter' | 'Transféré'; attendance: number; totalDue: number; paid: number;
  section: string; history: { year: string; className: string; decision: string }[];
};
type Staff = { id: string; name: string; role: string; email: string; status: 'Disponible' | 'Présent' | 'Absent'; classes: string[]; subjects: string[]; hours: number };
type ClassRoom = { id: string; name: string; level: string; group: string; section: string; titular: string; students: number; capacity: number };
type Payment = { id: string; studentId: string; studentName: string; amount: number; method: string; motif: string; date: string; status: 'Confirmé' | 'À rapprocher' };
type TimetableEntry = { id: string; day: string; start: string; end: string; subject: string; className: string; teacher: string; room: string };
type Message = { id: string; from: string; to: string; content: string; date: string; read: boolean };
type QRToken = { id: string; profileId: string; profileName: string; role: string; createdAt: number; expiresAt: number; status: 'pending' | 'used' | 'revoked' | 'expired'; dataUrl?: string };
type SchoolConfig = { name: string; form: string; legalStatus: string; address: string; phone: string; year: string; enabledLevels: string[]; gradingScale: number; rankingEnabled: boolean; reminderEnabled: boolean };

